function cloneRig(source){const c=source.clone(true),sa=[],ca=[];source.traverse(x=>sa.push(x));c.traverse(x=>ca.push(x));const map=new Map(sa.map((x,i)=>[x,ca[i]]));c.traverse(o=>{if(o.isSkinnedMesh){const s=sa[ca.indexOf(o)];o.skeleton=s.skeleton.clone();o.skeleton.bones=s.skeleton.bones.map(b=>map.get(b));o.bindMatrix.copy(s.bindMatrix);o.bind(o.skeleton,o.bindMatrix);}});return c;}
